using System;using System.Collections;using System.Collections.Generic;using System.Reflection;using System.IO;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;
public class DigitalKingdomSceneValidation:MonoBehaviour {
 void Awake(){DontDestroyOnLoad(gameObject);}
 public void Run(){StartCoroutine(Checks());}
 IEnumerator WaitScene(string path){float end=Time.realtimeSinceStartup+10;while(SceneManager.GetActiveScene().path!=path&&Time.realtimeSinceStartup<end)yield return null;yield return null;}
 IEnumerator Checks(){var f=BindingFlags.NonPublic|BindingFlags.Instance;var t=typeof(DungeonPrototype);var d=UnityEngine.Object.FindFirstObjectByType<DungeonPrototype>();var original=JsonUtility.FromJson<DungeonSaveData>(JsonUtility.ToJson(d.CaptureDungeonSave()));var source=SceneManager.GetActiveScene().path;var entry=DungeonMapSettings.Current.entities.objects.Find(e=>e.cityEntrance);var fixture=JsonUtility.FromJson<DungeonSaveData>(JsonUtility.ToJson(original));fixture.cell=entry.cell;fixture.heading=entry.heading;fixture.introductionCompleted=true;fixture.city=new DigitalKingdomProgress();fixture.refuge.refugeTragedyTriggered=false;fixture.refuge.unlockedNodes=new List<string>{"node.refuge"};var boss=fixture.enemies.Find(e=>e.placementId==DigitalKingdomSettings.Current.requiredBossId);var results=new List<string>();Action<bool,string> check=(ok,text)=>results.Add((ok?"PASS ":"FAIL ")+text);string oldTestPath=DungeonSaveStore.editorTestPath;var input=InputSystem.settings;var focus=input.editorInputBehaviorInPlayMode;var background=input.backgroundBehavior;input.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;input.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;
  try{
   d.enabled=false;boss.defeated=false;boss.currentHP=Mathf.Max(1,boss.currentHP);d.RestoreDungeonSave(fixture);t.GetField("startMenuOpen",f).SetValue(d,false);check(!d.EnterDigitalKingdom(),"Gate blocks access before Makong");boss.defeated=true;boss.currentHP=0;d.RestoreDungeonSave(fixture);t.GetField("startMenuOpen",f).SetValue(d,false);var doors=(Dictionary<string,DungeonDoor>)t.GetField("mapDoors",f).GetValue(d);doors[entry.id].SetOpenImmediately();d.StartCoroutine((IEnumerator)t.GetMethod("Move",f).Invoke(d,new object[]{1,0}));yield return WaitScene(DigitalKingdomSettings.Current.scenePath);
   var controller=UnityEngine.Object.FindFirstObjectByType<DigitalKingdomController>();if(controller==null)throw new Exception("City scene did not load");controller.enabled=false;d=controller.stateHost;check(!SceneManager.GetSceneByPath(source).isLoaded&&SceneManager.GetActiveScene().path==DigitalKingdomSettings.Current.scenePath,"City Single scene replaces the dungeon scene");check(UnityEngine.Object.FindObjectsByType<EnemyCombatStats>().Length==0&&UnityEngine.Object.FindObjectsByType<DungeonWallLamp>().Length==0,"Dungeon actors and geometry unloaded");check(d.GetComponents<CombatHack>().Length==0,"No minigames built in city");check(!d.enabled,"World controller dormant in city");check(!AudioListener.pause,"City UI sound is not paused");
   var dialog=(WorldDialogue)t.GetField("worldDialogue",f).GetValue(d);Action finish=()=>{int n=0;while(dialog.Active&&n++<40){dialog.CompleteLetters();dialog.Advance(50);}};finish();var state=d.CaptureDungeonSave();check(state.city.firstVisitCompleted&&state.city.returnCell==entry.cell,"First visit and real return point recorded");
   var keyboard=InputSystem.AddDevice<Keyboard>();InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.DownArrow));InputSystem.Update();keyboard.MakeCurrent();d.TickCityModel();check((int)t.GetField("citySelection",f).GetValue(d)==1,"Keyboard selects next option");yield return null;InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.Update();var pad=InputSystem.AddDevice<Gamepad>();InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.DpadDown));InputSystem.Update();pad.MakeCurrent();d.TickCityModel();check((int)t.GetField("citySelection",f).GetValue(d)==2,"Gamepad selects next option");yield return null;InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.South));InputSystem.Update();d.TickCityModel();check(d.CaptureDungeonSave().city.locationId=="city.temple","Gamepad A opens Temple");finish();yield return null;InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.East));InputSystem.Update();d.TickCityModel();check(string.IsNullOrEmpty(d.CaptureDungeonSave().city.locationId),"Gamepad B returns to city");InputSystem.RemoveDevice(pad);InputSystem.RemoveDevice(keyboard);
   foreach(var l in DigitalKingdomSettings.Current.locations){if(l.service==DigitalKingdomService.Exit)continue;check(d.OpenCityLocation(l.id),"Open "+l.id);finish();t.GetMethod("LeaveCityLocation",f).Invoke(d,null);}
   d.OpenCityLocation("city.temple");finish();t.GetField("hp",f).SetValue(d,1);d.RegisterCityTemple();state=d.CaptureDungeonSave();check(state.player.currentHP==(int)t.GetProperty("MaximumHP",f).GetValue(d)&&state.city.templeRegistered,"Temple heals and registers Continue");Directory.CreateDirectory("Tests");DungeonSaveStore.editorTestPath=Path.GetFullPath("Tests/CitySceneSave.json");DungeonSaveStore.Write(state,0,"City scene fixture");d.RestoreDungeonSave(DungeonSaveStore.Read(0));dialog=(WorldDialogue)t.GetField("worldDialogue",f).GetValue(d);finish();check(d.CaptureDungeonSave().city.inCity&&d.CaptureDungeonSave().city.templeRegistered,"Save restores directly within city scene");var nodes=(List<TransferNodeDefinition>)t.GetMethod("CityTravelNodes",f).Invoke(d,null);check(nodes.Count==1&&nodes[0].id=="node.refuge","Only discovered travel destinations listed");check(!(bool)t.GetMethod("CityTravel",f).Invoke(d,new object[]{"node.zone2"}),"Locked node rejected");
   t.GetMethod("LeaveCityLocation",f).Invoke(d,null);t.GetField("cityTransition",f).SetValue(d,Time.unscaledTime-1);controller.enabled=true;Directory.CreateDirectory("Captures/DigitalKingdom");ScreenCapture.CaptureScreenshot("Captures/DigitalKingdom/FullScreenCity.png");yield return new WaitForEndOfFrame();state=d.CaptureDungeonSave();d.ExitDigitalKingdom();yield return WaitScene(source);d=UnityEngine.Object.FindFirstObjectByType<DungeonPrototype>();d.enabled=false;var back=d.CaptureDungeonSave();check(back.cell==entry.cell,"Exit City restores exact dungeon entrance");check(back.enemies.Count==state.enemies.Count&&back.explored.Count==state.explored.Count&&back.entityStates.Count==state.entityStates.Count,"Return preserves enemies, map and object states");check(back.player.level==state.player.level&&back.player.experience==state.player.experience&&back.player.coins==state.player.coins,"Return preserves level XP and inventory currency");check(back.player.inventory.Count==state.player.inventory.Count&&back.player.inventory.TrueForAll(i=>state.player.inventory.Exists(j=>j.itemId==i.itemId&&j.quantity==i.quantity))&&string.Join(";",back.player.equipmentIds)==string.Join(";",state.player.equipmentIds),"Return preserves item and equipment IDs");
   t.GetMethod("WarpPlayer",f).Invoke(d,new object[]{entry.cell,entry.heading});d.EnterDigitalKingdom();yield return WaitScene(DigitalKingdomSettings.Current.scenePath);controller=UnityEngine.Object.FindFirstObjectByType<DigitalKingdomController>();controller.enabled=false;d=controller.stateHost;dialog=(WorldDialogue)t.GetField("worldDialogue",f).GetValue(d);check(!dialog.Active,"Revisit does not repeat discovery");check((bool)t.GetMethod("CityTravel",f).Invoke(d,new object[]{"node.refuge"}),"Travel to discovered node accepted");yield return WaitScene(source);d=UnityEngine.Object.FindFirstObjectByType<DungeonPrototype>();d.enabled=false;check(d.CaptureDungeonSave().cell==Array.Find(RefugeSettings.Current.nodes,n=>n.id=="node.refuge").cell,"Travel restores dungeon at registered node");
   t.GetField("hp",f).SetValue(d,0);t.GetField("lost",f).SetValue(d,true);check((bool)t.GetMethod("TryCityRespawn",f).Invoke(d,null),"Defeat with Continue transitions to kingdom");yield return WaitScene(DigitalKingdomSettings.Current.scenePath);controller=UnityEngine.Object.FindFirstObjectByType<DigitalKingdomController>();controller.enabled=false;d=controller.stateHost;state=d.CaptureDungeonSave();check(state.player.currentHP>0&&state.city.locationId=="city.temple","Respawn at Temple with restored HP");
  }finally{
   input.editorInputBehaviorInPlayMode=focus;input.backgroundBehavior=background;DungeonSaveStore.editorTestPath=oldTestPath;File.WriteAllLines("Tests/DigitalKingdomSceneMcpResults.txt",results);Debug.Log("City scene tests\n"+string.Join("\n",results.ToArray()));
   if(SceneManager.GetActiveScene().path!=source){original.city=original.city??new DigitalKingdomProgress();original.city.inCity=false;DigitalKingdomTransit.ReturnData=original;DigitalKingdomTransit.Map=DungeonMapSettings.Current;Time.timeScale=1;AudioListener.pause=false;SceneManager.LoadScene(source,LoadSceneMode.Single);}else{d=UnityEngine.Object.FindFirstObjectByType<DungeonPrototype>();if(d!=null){d.RestoreDungeonSave(original);d.enabled=true;}}
  }
 }
}
#endif
